PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE test_migration_check (   id TEXT PRIMARY KEY );
CREATE TABLE users (   user_id TEXT PRIMARY KEY,   full_name TEXT NOT NULL,   email TEXT COLLATE NOCASE UNIQUE,   account_status TEXT NOT NULL DEFAULT 'ACTIVE'     CHECK (account_status IN ('ACTIVE','SUSPENDED','DISABLED')),   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE roles (   role_id TEXT PRIMARY KEY,   role_code TEXT NOT NULL UNIQUE,   role_name TEXT NOT NULL,   description TEXT );
CREATE TABLE user_roles (   user_id TEXT NOT NULL REFERENCES users(user_id),   role_id TEXT NOT NULL REFERENCES roles(role_id),   assigned_by TEXT REFERENCES users(user_id),   assigned_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   PRIMARY KEY (user_id, role_id) );
CREATE TABLE jemaah (   jemaah_id TEXT PRIMARY KEY,   jemaah_code TEXT NOT NULL UNIQUE,   jemaah_name TEXT NOT NULL,   description TEXT,   status TEXT NOT NULL DEFAULT 'ACTIVE'     CHECK (status IN ('ACTIVE','INACTIVE','ARCHIVED')),   created_by TEXT NOT NULL REFERENCES users(user_id),   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) , country_id TEXT REFERENCES countries(country_id));
CREATE TABLE jemaah_memberships (   membership_id TEXT PRIMARY KEY,   jemaah_id TEXT NOT NULL REFERENCES jemaah(jemaah_id),   user_id TEXT NOT NULL REFERENCES users(user_id),   membership_status TEXT NOT NULL DEFAULT 'ACTIVE'     CHECK (membership_status IN ('ACTIVE','ENDED','REMOVED')),   joined_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   ended_at TEXT,   ended_by TEXT REFERENCES users(user_id),   end_reason TEXT,   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE takazas (   takaza_id TEXT PRIMARY KEY,   takaza_code TEXT NOT NULL UNIQUE,   jemaah_id TEXT NOT NULL REFERENCES jemaah(jemaah_id),   parent_takaza_id TEXT REFERENCES takazas(takaza_id),   takaza_name TEXT NOT NULL,   description TEXT,   status TEXT NOT NULL DEFAULT 'DRAFT'     CHECK (status IN ('DRAFT','RELEASED','ACTIVE','ON_HOLD','COMPLETED','CANCELLED')),   proposed_start_date TEXT,   official_start_date TEXT,   start_date_locked_at TEXT,   end_date TEXT,   created_by TEXT NOT NULL REFERENCES users(user_id),   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE takaza_participations (   participation_id TEXT PRIMARY KEY,   takaza_id TEXT NOT NULL REFERENCES takazas(takaza_id),   user_id TEXT NOT NULL REFERENCES users(user_id),   participation_status TEXT NOT NULL DEFAULT 'PENDING'     CHECK (participation_status IN ('PENDING','ACTIVE','ENDED','WITHDRAWN','REMOVED')),   participation_source TEXT NOT NULL DEFAULT 'VOLUNTARY'     CHECK (participation_source IN ('VOLUNTARY','ADMIN_NOMINATED','ADMIN_ASSIGNED')),   accepted_at TEXT,   started_at TEXT,   ended_at TEXT,   ended_by TEXT REFERENCES users(user_id),   end_reason TEXT,   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),    UNIQUE (participation_id, takaza_id, user_id) );
CREATE TABLE amer_appointments (   appointment_id TEXT PRIMARY KEY,   takaza_id TEXT NOT NULL REFERENCES takazas(takaza_id),   participation_id TEXT NOT NULL,   appointee_user_id TEXT NOT NULL REFERENCES users(user_id),   eligibility_status TEXT NOT NULL     CHECK (eligibility_status IN ('ELIGIBLE','PENDING','INELIGIBLE')),   eligibility_reference TEXT,   appointed_by TEXT NOT NULL REFERENCES users(user_id),   appointed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   effective_at TEXT NOT NULL,   ended_at TEXT,   ended_by TEXT REFERENCES users(user_id),   change_reason TEXT,   former_access_policy TEXT NOT NULL DEFAULT 'ADMIN_CONTROLLED'     CHECK (former_access_policy IN ('ADMIN_CONTROLLED','READ_ONLY','NO_ACCESS')),    CHECK (     eligibility_status <> 'ELIGIBLE'     OR (       eligibility_reference IS NOT NULL       AND length(trim(eligibility_reference)) > 0     )   ),    FOREIGN KEY (participation_id, takaza_id, appointee_user_id)     REFERENCES takaza_participations(participation_id, takaza_id, user_id) );
CREATE TABLE audit_logs (   audit_id TEXT PRIMARY KEY,   actor_user_id TEXT REFERENCES users(user_id),   action TEXT NOT NULL,   entity_type TEXT NOT NULL,   entity_id TEXT NOT NULL,   before_json TEXT,   after_json TEXT,   reason TEXT,   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) , country_id TEXT REFERENCES countries(country_id));
CREATE TABLE user_auth_identities (   identity_id TEXT PRIMARY KEY,   user_id TEXT NOT NULL REFERENCES users(user_id),   identity_type TEXT NOT NULL CHECK (identity_type IN ('NATIONAL_ID','EMAIL','WHATSAPP','PASSPORT')),   country_code TEXT,   identity_scope TEXT NOT NULL,   identity_hash TEXT NOT NULL,   hash_key_version INTEGER NOT NULL CHECK (hash_key_version > 0),   encrypted_value TEXT NOT NULL,   verification_status TEXT NOT NULL DEFAULT 'PENDING' CHECK (verification_status IN ('PENDING','VERIFIED','EXPIRED','REVOKED')),   expires_at TEXT,   verified_at TEXT,   revoked_at TEXT,   revoked_by TEXT REFERENCES users(user_id),   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), verification_method TEXT CHECK (   verification_method IS NULL   OR verification_method IN ('OTP', 'ADMIN_MANUAL') ), verified_by TEXT REFERENCES users(user_id),   CHECK (length(trim(identity_scope)) > 0),   CHECK (length(trim(identity_hash)) > 0),   CHECK (length(trim(encrypted_value)) > 0),   CHECK (     (identity_type IN ('NATIONAL_ID','PASSPORT') AND country_code IS NOT NULL AND country_code GLOB '[A-Z][A-Z]' AND identity_scope = country_code)     OR     (identity_type IN ('EMAIL','WHATSAPP') AND country_code IS NULL AND identity_scope = 'GLOBAL')   ),   CHECK (verification_status <> 'PENDING' OR expires_at IS NOT NULL),   CHECK (verification_status <> 'VERIFIED' OR verified_at IS NOT NULL),   CHECK (     (verification_status = 'REVOKED' AND revoked_at IS NOT NULL)     OR     (verification_status <> 'REVOKED' AND revoked_at IS NULL)   ),   CHECK (revoked_by IS NULL OR verification_status = 'REVOKED'),   UNIQUE (identity_id, user_id) );
CREATE TABLE user_credentials (   credential_id TEXT PRIMARY KEY,   user_id TEXT NOT NULL REFERENCES users(user_id),   credential_type TEXT NOT NULL CHECK (credential_type = 'PASSWORD'),   password_hash TEXT NOT NULL CHECK (length(trim(password_hash)) > 0),   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   changed_at TEXT,   revoked_at TEXT );
CREATE TABLE auth_otp_requests (   otp_request_id TEXT PRIMARY KEY,   user_id TEXT REFERENCES users(user_id),   identity_id TEXT,   otp_purpose TEXT NOT NULL CHECK (otp_purpose IN ('REGISTER','LOGIN','VERIFY_IDENTITY','RESET_PASSWORD')),   destination_type TEXT NOT NULL CHECK (destination_type IN ('EMAIL','WHATSAPP')),   destination_hash TEXT NOT NULL CHECK (length(trim(destination_hash)) > 0),   destination_encrypted TEXT NOT NULL CHECK (length(trim(destination_encrypted)) > 0),   destination_hash_key_version INTEGER NOT NULL CHECK (destination_hash_key_version > 0),   otp_hash TEXT NOT NULL CHECK (length(trim(otp_hash)) > 0),   otp_hash_key_version INTEGER NOT NULL CHECK (otp_hash_key_version > 0),   expires_at TEXT NOT NULL,   attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),   max_attempts INTEGER NOT NULL DEFAULT 5 CHECK (max_attempts > 0),   last_sent_at TEXT NOT NULL,   consumed_at TEXT,   invalidated_at TEXT,   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   CHECK (identity_id IS NULL OR user_id IS NOT NULL),   CHECK (identity_id IS NOT NULL OR otp_purpose = 'REGISTER'),   CHECK (attempt_count <= max_attempts),   CHECK (consumed_at IS NULL OR invalidated_at IS NULL),   FOREIGN KEY (identity_id, user_id)     REFERENCES user_auth_identities(identity_id, user_id) );
CREATE TABLE user_sessions (   session_id TEXT PRIMARY KEY,   user_id TEXT NOT NULL REFERENCES users(user_id),   token_hash TEXT NOT NULL UNIQUE CHECK (length(trim(token_hash)) > 0),   device_name TEXT,   device_type TEXT NOT NULL DEFAULT 'OTHER' CHECK (device_type IN ('MOBILE','TABLET','DESKTOP','OTHER')),   ip_address TEXT,   user_agent TEXT,   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   last_activity_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   expires_at TEXT NOT NULL,   revoked_at TEXT,   revocation_reason TEXT CHECK (     revocation_reason IS NULL OR revocation_reason IN ('LOGOUT','LOGOUT_ALL','PASSWORD_CHANGED','PASSWORD_RESET','ACCOUNT_SUSPENDED','USER_REVOKED','ADMIN_REVOKED','SESSION_EXPIRED','SECURITY_ACTION')   ),   CHECK (     (revoked_at IS NULL AND revocation_reason IS NULL)     OR     (revoked_at IS NOT NULL AND revocation_reason IS NOT NULL)   ),   UNIQUE (session_id, user_id) );
CREATE TABLE auth_events (   event_id TEXT PRIMARY KEY,   user_id TEXT REFERENCES users(user_id),   session_id TEXT,   event_type TEXT NOT NULL,   event_status TEXT NOT NULL CHECK (event_status IN ('SUCCESS','FAILED')),   ip_address TEXT,   user_agent TEXT,   event_details TEXT CHECK (event_details IS NULL OR json_valid(event_details)),   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   CHECK (session_id IS NULL OR user_id IS NOT NULL),   FOREIGN KEY (session_id, user_id)     REFERENCES user_sessions(session_id, user_id) );
CREATE TABLE user_activation_tokens (   activation_token_id TEXT PRIMARY KEY,   user_id TEXT NOT NULL REFERENCES users(user_id),   token_hash TEXT NOT NULL CHECK (length(trim(token_hash)) > 0),   hash_key_version INTEGER NOT NULL CHECK (hash_key_version > 0),   expires_at TEXT NOT NULL,   consumed_at TEXT,   invalidated_at TEXT,   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   CHECK (consumed_at IS NULL OR invalidated_at IS NULL) );
CREATE TABLE auth_rate_limits (   rate_limit_scope TEXT NOT NULL     CHECK (length(trim(rate_limit_scope)) > 0),   rate_limit_id TEXT NOT NULL     CHECK (length(trim(rate_limit_id)) > 0),   window_started_at TEXT NOT NULL,   request_count INTEGER NOT NULL DEFAULT 0     CHECK (request_count >= 0),   expires_at TEXT NOT NULL,   created_at TEXT NOT NULL     DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   updated_at TEXT NOT NULL     DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   PRIMARY KEY (     rate_limit_scope,     rate_limit_id,     window_started_at   ) );
CREATE TABLE user_registration_reviews (   user_id TEXT PRIMARY KEY REFERENCES users(user_id),   registration_status TEXT NOT NULL DEFAULT 'AWAITING_EMAIL_VERIFICATION'     CHECK (registration_status IN (       'AWAITING_EMAIL_VERIFICATION',       'PENDING_REVIEW',       'APPROVED',       'REJECTED',       'CANCELLED'     )),   reviewed_by TEXT REFERENCES users(user_id),   reviewed_at TEXT,   rejection_reason TEXT,   cancellation_reason TEXT,   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), admin_assisted_recovery_at TEXT, admin_assisted_recovery_by TEXT REFERENCES users(user_id), admin_assisted_recovery_method TEXT CHECK (   admin_assisted_recovery_method IS NULL   OR admin_assisted_recovery_method IN (     'ORIGINAL_DOCUMENT_CHECK',     'DIRECT_CONTACT',     'OTHER'   ) ), admin_assisted_recovery_reason TEXT,   CHECK (     (       registration_status IN ('AWAITING_EMAIL_VERIFICATION','PENDING_REVIEW')       AND reviewed_by IS NULL       AND reviewed_at IS NULL     )     OR     (       registration_status IN ('APPROVED','REJECTED','CANCELLED')       AND reviewed_by IS NOT NULL       AND reviewed_at IS NOT NULL     )   ),   CHECK (     (       registration_status = 'REJECTED'       AND rejection_reason IS NOT NULL       AND length(trim(rejection_reason)) > 0     )     OR     (registration_status <> 'REJECTED' AND rejection_reason IS NULL)   ),   CHECK (     (       registration_status = 'CANCELLED'       AND cancellation_reason IS NOT NULL       AND length(trim(cancellation_reason)) > 0     )     OR     (registration_status <> 'CANCELLED' AND cancellation_reason IS NULL)   ) );
CREATE TABLE user_registration_identity_details (   detail_id TEXT PRIMARY KEY,   user_id TEXT NOT NULL REFERENCES users(user_id),   identity_type TEXT NOT NULL     CHECK (identity_type IN ('NATIONAL_ID','WHATSAPP')),   country_code TEXT,   identity_scope TEXT NOT NULL,   identity_hash TEXT NOT NULL,   hash_key_version INTEGER NOT NULL CHECK (hash_key_version > 0),   encrypted_value TEXT NOT NULL,   identity_status TEXT NOT NULL DEFAULT 'UNVERIFIED'     CHECK (identity_status IN ('UNVERIFIED','VERIFIED','REVOKED')),   released_at TEXT,   released_by TEXT REFERENCES users(user_id),   release_reason TEXT,   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   CHECK (length(trim(identity_hash)) > 0),   CHECK (length(trim(encrypted_value)) > 0),   CHECK (length(trim(identity_scope)) > 0),   CHECK (     (       identity_type = 'NATIONAL_ID'       AND country_code IS NOT NULL       AND country_code GLOB '[A-Z][A-Z]'       AND identity_scope = country_code     )     OR     (       identity_type = 'WHATSAPP'       AND country_code IS NULL       AND identity_scope = 'GLOBAL'     )   ),   CHECK (     (       identity_status = 'REVOKED'       AND released_at IS NOT NULL       AND released_by IS NOT NULL       AND release_reason IS NOT NULL       AND length(trim(release_reason)) > 0     )     OR     (       identity_status <> 'REVOKED'       AND released_at IS NULL       AND released_by IS NULL       AND release_reason IS NULL     )   ),   UNIQUE (detail_id, user_id) );
CREATE TABLE countries (   country_id TEXT PRIMARY KEY,   country_code TEXT NOT NULL UNIQUE,   country_name TEXT NOT NULL,   country_status TEXT NOT NULL DEFAULT 'ACTIVE'     CHECK (country_status IN ('ACTIVE', 'INACTIVE')),   created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),   updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),    CHECK (country_code GLOB '[A-Z][A-Z]'),   CHECK (country_id = country_code),   CHECK (length(trim(country_name)) > 0) );
CREATE TABLE user_country_assignments (   assignment_id TEXT PRIMARY KEY,   user_id TEXT NOT NULL REFERENCES users(user_id),   country_id TEXT NOT NULL REFERENCES countries(country_id),    assignment_role_code TEXT NOT NULL DEFAULT 'ADMIN'     CHECK (assignment_role_code = 'ADMIN'),    assignment_status TEXT NOT NULL DEFAULT 'ACTIVE'     CHECK (assignment_status IN ('ACTIVE', 'REVOKED')),    assigned_by TEXT REFERENCES users(user_id),   assigned_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),    revoked_by TEXT REFERENCES users(user_id),   revoked_at TEXT,   revocation_reason TEXT,    CHECK (     (       assignment_status = 'ACTIVE'       AND revoked_by IS NULL       AND revoked_at IS NULL       AND revocation_reason IS NULL     )     OR     (       assignment_status = 'REVOKED'       AND revoked_by IS NOT NULL       AND revoked_at IS NOT NULL       AND revocation_reason IS NOT NULL       AND length(trim(revocation_reason)) > 0     )   ) );
CREATE TABLE super_admin_bootstrap_state (     bootstrap_id INTEGER PRIMARY KEY CHECK (bootstrap_id = 1),     user_id TEXT NOT NULL UNIQUE REFERENCES users(user_id),     bootstrap_status TEXT NOT NULL DEFAULT 'PENDING'         CHECK (bootstrap_status IN ('PENDING', 'COMPLETE')),     completed_at TEXT,     created_at TEXT NOT NULL         DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     updated_at TEXT NOT NULL         DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     CHECK (         (bootstrap_status = 'PENDING' AND completed_at IS NULL)         OR         (bootstrap_status = 'COMPLETE' AND completed_at IS NOT NULL)     ) );
CREATE TABLE super_admin_bootstrap_tokens (     bootstrap_token_id TEXT PRIMARY KEY,     user_id TEXT NOT NULL         REFERENCES super_admin_bootstrap_state(user_id),     token_hash TEXT NOT NULL UNIQUE,     hash_key_version INTEGER NOT NULL DEFAULT 1         CHECK (hash_key_version > 0),     expires_at TEXT NOT NULL,     consumed_at TEXT,     invalidated_at TEXT,     created_at TEXT NOT NULL         DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     CHECK (         consumed_at IS NULL         OR invalidated_at IS NULL     ) );
CREATE TABLE user_account_archives (     archive_id TEXT PRIMARY KEY,     user_id TEXT NOT NULL REFERENCES users(user_id),     previous_account_status TEXT NOT NULL         CHECK (previous_account_status IN ('ACTIVE', 'DISABLED')),     archived_by TEXT NOT NULL REFERENCES users(user_id),     archive_reason TEXT NOT NULL         CHECK (length(trim(archive_reason)) BETWEEN 10 AND 1000),     archived_at TEXT NOT NULL,     restored_by TEXT REFERENCES users(user_id),     restored_at TEXT,     restore_reason TEXT,     CHECK (         (             restored_by IS NULL             AND restored_at IS NULL             AND restore_reason IS NULL         )         OR         (             restored_by IS NOT NULL             AND restored_at IS NOT NULL             AND restore_reason IS NOT NULL             AND length(trim(restore_reason)) BETWEEN 10 AND 1000         )     ) );
CREATE TABLE user_profiles (     user_id TEXT PRIMARY KEY,     full_name TEXT,     date_of_birth TEXT,     created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     FOREIGN KEY (user_id) REFERENCES users(user_id) );
CREATE TABLE admin_assisted_recovery_tokens (   recovery_token_id TEXT PRIMARY KEY,   user_id TEXT NOT NULL REFERENCES users(user_id),   token_hash TEXT NOT NULL     CHECK (length(trim(token_hash)) > 0),   hash_key_version INTEGER NOT NULL     CHECK (hash_key_version > 0),   expires_at TEXT NOT NULL,   created_by TEXT NOT NULL REFERENCES users(user_id),   consumed_at TEXT,   invalidated_at TEXT,   created_at TEXT NOT NULL     DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),   CHECK (consumed_at IS NULL OR invalidated_at IS NULL) );
CREATE TABLE user_email_change_otp_requests (   otp_id TEXT PRIMARY KEY,   request_id TEXT NOT NULL,   user_id TEXT NOT NULL,    destination_hash TEXT NOT NULL     CHECK (length(trim(destination_hash)) > 0),    destination_encrypted TEXT NOT NULL     CHECK (length(trim(destination_encrypted)) > 0),    destination_hash_key_version INTEGER NOT NULL     CHECK (destination_hash_key_version > 0),    otp_hash TEXT NOT NULL     CHECK (length(trim(otp_hash)) > 0),    otp_hash_key_version INTEGER NOT NULL     CHECK (otp_hash_key_version > 0),    delivery_method TEXT NOT NULL     CHECK (delivery_method IN ('AUTOMATIC', 'ADMIN_ASSISTED')),    issued_by TEXT REFERENCES users(user_id),   issued_at TEXT NOT NULL,   expires_at TEXT NOT NULL,    attempt_count INTEGER NOT NULL DEFAULT 0     CHECK (attempt_count >= 0),    max_attempts INTEGER NOT NULL DEFAULT 5     CHECK (max_attempts > 0),    delivered_at TEXT,   consumed_at TEXT,   invalidated_at TEXT,    created_at TEXT NOT NULL     DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),    CHECK (attempt_count <= max_attempts),    CHECK (     (delivery_method = 'ADMIN_ASSISTED' AND issued_by IS NOT NULL)     OR     (delivery_method = 'AUTOMATIC' AND issued_by IS NULL)   ),    CHECK (consumed_at IS NULL OR invalidated_at IS NULL),    FOREIGN KEY (request_id, user_id)     REFERENCES user_email_change_requests(request_id, user_id) );
CREATE TABLE IF NOT EXISTS "user_email_change_requests" (   request_id TEXT PRIMARY KEY,    user_id TEXT NOT NULL     REFERENCES users(user_id),    requested_email_hash TEXT NOT NULL     CHECK (length(trim(requested_email_hash)) > 0),    requested_email_encrypted TEXT NOT NULL     CHECK (length(trim(requested_email_encrypted)) > 0),    hash_key_version INTEGER NOT NULL     CHECK (hash_key_version > 0),    request_status TEXT NOT NULL DEFAULT 'PENDING'     CHECK (request_status IN (       'PENDING',       'APPROVED',       'REJECTED',       'CANCELLED',       'SUPERSEDED'     )),    identity_check_method TEXT NOT NULL     DEFAULT 'PASSWORD_NATIONAL_ID_WHATSAPP'     CHECK (       identity_check_method = 'PASSWORD_NATIONAL_ID_WHATSAPP'     ),    submitted_at TEXT NOT NULL     DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),    reviewed_by TEXT REFERENCES users(user_id),   reviewed_at TEXT,   review_reason TEXT,    email_verified_at TEXT,   applied_at TEXT,    created_at TEXT NOT NULL     DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),    updated_at TEXT NOT NULL     DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),    CHECK (     (       request_status = 'PENDING'       AND reviewed_by IS NULL       AND reviewed_at IS NULL       AND review_reason IS NULL       AND email_verified_at IS NULL       AND applied_at IS NULL     )     OR     (       request_status = 'APPROVED'       AND reviewed_by IS NOT NULL       AND reviewed_at IS NOT NULL       AND review_reason IS NOT NULL       AND length(trim(review_reason)) > 0     )     OR     (       request_status IN ('REJECTED', 'CANCELLED', 'SUPERSEDED')       AND reviewed_by IS NOT NULL       AND reviewed_at IS NOT NULL       AND review_reason IS NOT NULL       AND length(trim(review_reason)) > 0       AND email_verified_at IS NULL       AND applied_at IS NULL     )   ),    CHECK (     applied_at IS NULL     OR email_verified_at IS NOT NULL   ),    UNIQUE (request_id, user_id) );
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX uq_jemaah_active_membership   ON jemaah_memberships(jemaah_id, user_id)   WHERE membership_status = 'ACTIVE';
CREATE UNIQUE INDEX uq_takaza_active_participation   ON takaza_participations(takaza_id, user_id)   WHERE participation_status IN ('PENDING','ACTIVE');
CREATE UNIQUE INDEX uq_takaza_current_amer   ON amer_appointments(takaza_id)   WHERE ended_at IS NULL;
CREATE INDEX idx_jemaah_memberships_user   ON jemaah_memberships(user_id, membership_status);
CREATE INDEX idx_takaza_participations_user   ON takaza_participations(user_id, participation_status);
CREATE INDEX idx_amer_appointments_takaza   ON amer_appointments(takaza_id, appointed_at);
CREATE INDEX idx_audit_entity   ON audit_logs(entity_type, entity_id, created_at);
CREATE UNIQUE INDEX uq_auth_identity_active ON user_auth_identities(identity_type, identity_scope, identity_hash) WHERE verification_status IN ('PENDING','VERIFIED');
CREATE INDEX idx_auth_identity_user ON user_auth_identities(user_id, verification_status);
CREATE INDEX idx_auth_identity_expiry ON user_auth_identities(expires_at) WHERE verification_status = 'PENDING';
CREATE UNIQUE INDEX uq_user_active_password ON user_credentials(user_id, credential_type) WHERE revoked_at IS NULL;
CREATE INDEX idx_user_credentials_user ON user_credentials(user_id);
CREATE INDEX idx_auth_otp_user ON auth_otp_requests(user_id, created_at);
CREATE INDEX idx_auth_otp_identity ON auth_otp_requests(identity_id, created_at);
CREATE INDEX idx_auth_otp_destination ON auth_otp_requests(destination_type, destination_hash);
CREATE INDEX idx_auth_otp_expiry ON auth_otp_requests(expires_at) WHERE consumed_at IS NULL AND invalidated_at IS NULL;
CREATE UNIQUE INDEX uq_auth_otp_active_destination ON auth_otp_requests(destination_type, destination_hash, otp_purpose) WHERE consumed_at IS NULL AND invalidated_at IS NULL;
CREATE INDEX idx_user_sessions_user ON user_sessions(user_id, created_at);
CREATE INDEX idx_user_sessions_active ON user_sessions(user_id, expires_at) WHERE revoked_at IS NULL;
CREATE INDEX idx_auth_events_user ON auth_events(user_id, created_at);
CREATE INDEX idx_auth_events_type ON auth_events(event_type, created_at);
CREATE INDEX idx_auth_events_created ON auth_events(created_at);
CREATE INDEX idx_auth_events_session ON auth_events(session_id);
CREATE UNIQUE INDEX uq_user_activation_token_active ON user_activation_tokens(user_id) WHERE consumed_at IS NULL AND invalidated_at IS NULL;
CREATE UNIQUE INDEX uq_user_activation_token_hash ON user_activation_tokens(token_hash);
CREATE INDEX idx_user_activation_token_expiry ON user_activation_tokens(expires_at) WHERE consumed_at IS NULL AND invalidated_at IS NULL;
CREATE INDEX idx_user_activation_token_user ON user_activation_tokens(user_id, created_at);
CREATE INDEX idx_auth_rate_limits_expiry ON auth_rate_limits(expires_at);
CREATE INDEX idx_auth_rate_limits_client ON auth_rate_limits(rate_limit_id, rate_limit_scope);
CREATE INDEX idx_registration_reviews_status ON user_registration_reviews(registration_status, created_at);
CREATE INDEX idx_registration_reviews_reviewer ON user_registration_reviews(reviewed_by, reviewed_at);
CREATE UNIQUE INDEX uq_registration_identity_claim ON user_registration_identity_details(   identity_type,   identity_scope,   identity_hash ) WHERE identity_status IN ('UNVERIFIED','VERIFIED');
CREATE INDEX idx_registration_identity_user ON user_registration_identity_details(user_id, identity_status);
CREATE INDEX idx_registration_identity_type ON user_registration_identity_details(   identity_type,   identity_scope,   identity_status );
CREATE UNIQUE INDEX uq_registration_identity_current_per_user ON user_registration_identity_details(user_id, identity_type) WHERE identity_status IN ('UNVERIFIED', 'VERIFIED');
CREATE UNIQUE INDEX uq_user_country_active_assignment ON user_country_assignments (   user_id,   country_id,   assignment_role_code ) WHERE assignment_status = 'ACTIVE';
CREATE INDEX idx_country_assignments_user ON user_country_assignments (   user_id,   assignment_status );
CREATE INDEX idx_country_assignments_country ON user_country_assignments (   country_id,   assignment_status );
CREATE INDEX idx_jemaah_country ON jemaah(country_id, status);
CREATE INDEX idx_audit_country ON audit_logs(country_id, created_at);
CREATE UNIQUE INDEX uq_super_admin_active_bootstrap_token ON super_admin_bootstrap_tokens(user_id) WHERE consumed_at IS NULL AND invalidated_at IS NULL;
CREATE INDEX idx_super_admin_bootstrap_token_expiry ON super_admin_bootstrap_tokens(expires_at) WHERE consumed_at IS NULL AND invalidated_at IS NULL;
CREATE UNIQUE INDEX uq_single_super_admin_role ON user_roles(role_id) WHERE role_id = 'role-super-admin';
CREATE UNIQUE INDEX uq_user_account_archives_active ON user_account_archives(user_id) WHERE restored_at IS NULL;
CREATE INDEX idx_user_account_archives_history ON user_account_archives(user_id, archived_at DESC);
CREATE INDEX idx_user_profiles_full_name ON user_profiles(full_name);
CREATE UNIQUE INDEX uq_admin_recovery_token_active ON admin_assisted_recovery_tokens(user_id) WHERE consumed_at IS NULL   AND invalidated_at IS NULL;
CREATE UNIQUE INDEX uq_admin_recovery_token_hash ON admin_assisted_recovery_tokens(token_hash);
CREATE INDEX idx_admin_recovery_token_expiry ON admin_assisted_recovery_tokens(expires_at) WHERE consumed_at IS NULL   AND invalidated_at IS NULL;
CREATE INDEX idx_admin_recovery_token_user ON admin_assisted_recovery_tokens(user_id, created_at);
CREATE INDEX idx_auth_identity_manual_verification ON user_auth_identities(verification_method, verified_by) WHERE verification_method = 'ADMIN_MANUAL';
CREATE INDEX idx_email_change_otp_request ON user_email_change_otp_requests(request_id, created_at);
CREATE INDEX idx_email_change_otp_expiry ON user_email_change_otp_requests(expires_at) WHERE consumed_at IS NULL   AND invalidated_at IS NULL;
CREATE UNIQUE INDEX uq_email_change_otp_active_request ON user_email_change_otp_requests(request_id) WHERE consumed_at IS NULL   AND invalidated_at IS NULL;
CREATE UNIQUE INDEX uq_email_change_otp_active_destination ON user_email_change_otp_requests(destination_hash) WHERE consumed_at IS NULL   AND invalidated_at IS NULL;
CREATE UNIQUE INDEX uq_user_email_change_pending ON user_email_change_requests(user_id) WHERE request_status = 'PENDING';
CREATE UNIQUE INDEX uq_user_email_change_pending_address ON user_email_change_requests(requested_email_hash) WHERE request_status = 'PENDING';
CREATE INDEX idx_user_email_change_status ON user_email_change_requests(request_status, submitted_at);
CREATE INDEX idx_user_email_change_user ON user_email_change_requests(user_id, submitted_at);
CREATE INDEX idx_user_email_change_reviewer ON user_email_change_requests(reviewed_by, reviewed_at);
CREATE TRIGGER trg_registration_otp_completion_guard BEFORE UPDATE OF consumed_at ON auth_otp_requests WHEN OLD.consumed_at IS NULL  AND NEW.consumed_at IS NOT NULL  AND NEW.otp_purpose = 'REGISTER' BEGIN   SELECT CASE     WHEN NOT (       NEW.otp_purpose = 'REGISTER'       AND NEW.destination_type = 'EMAIL'       AND NEW.user_id IS NOT NULL       AND NEW.identity_id IS NOT NULL       AND NEW.invalidated_at IS NULL       AND NEW.expires_at > NEW.consumed_at       AND NEW.attempt_count < NEW.max_attempts       AND EXISTS (         SELECT 1         FROM user_auth_identities i         WHERE i.identity_id = NEW.identity_id           AND i.user_id = NEW.user_id           AND i.identity_type = 'EMAIL'           AND i.identity_scope = 'GLOBAL'           AND i.verification_status = 'VERIFIED'           AND i.verified_at IS NOT NULL           AND i.expires_at IS NULL       )       AND EXISTS (         SELECT 1         FROM users u         WHERE u.user_id = NEW.user_id           AND u.email IS NOT NULL           AND u.account_status = 'DISABLED'       )       AND EXISTS (         SELECT 1         FROM user_registration_reviews r         WHERE r.user_id = NEW.user_id           AND r.registration_status = 'PENDING_REVIEW'           AND r.reviewed_by IS NULL           AND r.reviewed_at IS NULL       )     )     THEN RAISE(       ABORT,       'Registration OTP completion state is incomplete.'     )   END; END;
CREATE TRIGGER trg_registration_review_apply_account_status AFTER UPDATE OF registration_status ON user_registration_reviews WHEN OLD.registration_status = 'PENDING_REVIEW'  AND NEW.registration_status IN ('APPROVED', 'REJECTED') BEGIN   UPDATE users   SET     account_status = CASE       WHEN NEW.registration_status = 'APPROVED'         THEN 'ACTIVE'       ELSE 'DISABLED'     END,     updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')   WHERE user_id = NEW.user_id; END;
CREATE TRIGGER trg_registration_review_audit AFTER UPDATE OF registration_status ON user_registration_reviews WHEN OLD.registration_status = 'PENDING_REVIEW'  AND NEW.registration_status IN ('APPROVED', 'REJECTED') BEGIN   INSERT INTO audit_logs (     audit_id,     actor_user_id,     action,     entity_type,     entity_id,     before_json,     after_json,     reason,     created_at   )   VALUES (     lower(hex(randomblob(16))),     NEW.reviewed_by,     CASE       WHEN NEW.registration_status = 'APPROVED'         THEN 'REGISTRATION_APPROVED'       ELSE 'REGISTRATION_REJECTED'     END,     'USER_REGISTRATION',     NEW.user_id,     json_object(       'registration_status', OLD.registration_status,       'account_status', 'DISABLED'     ),     json_object(       'registration_status', NEW.registration_status,       'account_status',         CASE           WHEN NEW.registration_status = 'APPROVED'             THEN 'ACTIVE'           ELSE 'DISABLED'         END,       'reviewed_by', NEW.reviewed_by,       'reviewed_at', NEW.reviewed_at     ),     CASE       WHEN NEW.registration_status = 'REJECTED'         THEN NEW.rejection_reason       ELSE NULL     END,     strftime('%Y-%m-%dT%H:%M:%fZ', 'now')   ); END;
CREATE TRIGGER trg_country_assignment_admin_role_insert BEFORE INSERT ON user_country_assignments WHEN NEW.assignment_status = 'ACTIVE' BEGIN   SELECT CASE     WHEN NOT EXISTS (       SELECT 1       FROM user_roles ur       JOIN roles r ON r.role_id = ur.role_id       WHERE ur.user_id = NEW.user_id         AND r.role_code = 'ADMIN'     )     THEN RAISE(ABORT, 'Country Admin must have ADMIN role.')   END;    SELECT CASE     WHEN NOT EXISTS (       SELECT 1       FROM countries c       WHERE c.country_id = NEW.country_id         AND c.country_status = 'ACTIVE'     )     THEN RAISE(ABORT, 'Country is not active.')   END; END;
CREATE TRIGGER trg_country_assignment_admin_role_update BEFORE UPDATE OF user_id, country_id, assignment_role_code, assignment_status ON user_country_assignments WHEN NEW.assignment_status = 'ACTIVE' BEGIN   SELECT CASE     WHEN NOT EXISTS (       SELECT 1       FROM user_roles ur       JOIN roles r ON r.role_id = ur.role_id       WHERE ur.user_id = NEW.user_id         AND r.role_code = 'ADMIN'     )     THEN RAISE(ABORT, 'Country Admin must have ADMIN role.')   END;    SELECT CASE     WHEN NOT EXISTS (       SELECT 1       FROM countries c       WHERE c.country_id = NEW.country_id         AND c.country_status = 'ACTIVE'     )     THEN RAISE(ABORT, 'Country is not active.')   END; END;
CREATE TRIGGER trg_jemaah_country_required_insert BEFORE INSERT ON jemaah WHEN NEW.country_id IS NULL BEGIN   SELECT RAISE(ABORT, 'Jemaah country is required.'); END;
CREATE TRIGGER trg_jemaah_country_required_update BEFORE UPDATE OF country_id ON jemaah WHEN NEW.country_id IS NULL BEGIN   SELECT RAISE(ABORT, 'Jemaah country is required.'); END;
CREATE TRIGGER trg_jemaah_country_immutable BEFORE UPDATE OF country_id ON jemaah WHEN OLD.country_id IS NOT NEW.country_id BEGIN   SELECT RAISE(ABORT, 'Jemaah country cannot be changed.'); END;
CREATE TRIGGER trg_super_admin_bootstrap_state_immutable BEFORE UPDATE OF user_id, bootstrap_id ON super_admin_bootstrap_state BEGIN     SELECT RAISE(ABORT, 'Bootstrap target is immutable.'); END;
CREATE TRIGGER trg_super_admin_bootstrap_state_complete_guard BEFORE UPDATE OF bootstrap_status ON super_admin_bootstrap_state WHEN NEW.bootstrap_status = 'COMPLETE' BEGIN     SELECT CASE         WHEN OLD.bootstrap_status <> 'PENDING'         THEN RAISE(ABORT, 'Bootstrap is already completed.')     END;      SELECT CASE         WHEN NOT EXISTS (             SELECT 1             FROM users u             INNER JOIN user_roles ur                 ON ur.user_id = u.user_id                 AND ur.role_id = 'role-super-admin'             INNER JOIN user_credentials c                 ON c.user_id = u.user_id                 AND c.credential_type = 'PASSWORD'                 AND c.revoked_at IS NULL             WHERE u.user_id = NEW.user_id               AND u.account_status = 'ACTIVE'         )         THEN RAISE(ABORT, 'Bootstrap prerequisites are incomplete.')     END;      SELECT CASE         WHEN NOT EXISTS (             SELECT 1             FROM super_admin_bootstrap_tokens t             WHERE t.user_id = NEW.user_id               AND t.consumed_at IS NOT NULL               AND t.invalidated_at IS NULL         )         THEN RAISE(ABORT, 'Bootstrap token has not been consumed.')     END;      SELECT CASE         WHEN NOT EXISTS (             SELECT 1             FROM audit_logs a             WHERE a.actor_user_id = NEW.user_id               AND a.action = 'SUPER_ADMIN_BOOTSTRAP'               AND a.entity_type = 'USER'               AND a.entity_id = NEW.user_id         )         THEN RAISE(ABORT, 'Bootstrap audit record is missing.')     END; END;
CREATE TRIGGER trg_super_admin_bootstrap_state_no_delete BEFORE DELETE ON super_admin_bootstrap_state BEGIN     SELECT RAISE(ABORT, 'Bootstrap state cannot be deleted.'); END;
CREATE TRIGGER trg_super_admin_bootstrap_token_insert_guard BEFORE INSERT ON super_admin_bootstrap_tokens BEGIN     SELECT CASE         WHEN NOT EXISTS (             SELECT 1             FROM super_admin_bootstrap_state s             WHERE s.user_id = NEW.user_id               AND s.bootstrap_status = 'PENDING'         )         THEN RAISE(ABORT, 'Bootstrap is not available.')     END;      SELECT CASE         WHEN EXISTS (             SELECT 1             FROM user_roles             WHERE role_id = 'role-super-admin'         )         THEN RAISE(ABORT, 'A SUPER_ADMIN already exists.')     END; END;
CREATE TRIGGER trg_super_admin_bootstrap_token_immutable BEFORE UPDATE OF bootstrap_token_id, user_id, token_hash ON super_admin_bootstrap_tokens BEGIN     SELECT RAISE(ABORT, 'Bootstrap token identity is immutable.'); END;
CREATE TRIGGER trg_super_admin_bootstrap_token_no_reactivation BEFORE UPDATE ON super_admin_bootstrap_tokens WHEN (     OLD.consumed_at IS NOT NULL     AND NEW.consumed_at IS NULL ) OR (     OLD.invalidated_at IS NOT NULL     AND NEW.invalidated_at IS NULL ) BEGIN     SELECT RAISE(ABORT, 'Bootstrap token cannot be reactivated.'); END;
CREATE TRIGGER trg_registration_cancellation_audit AFTER UPDATE OF registration_status ON user_registration_reviews WHEN OLD.registration_status = 'AWAITING_EMAIL_VERIFICATION'  AND NEW.registration_status = 'CANCELLED' BEGIN   INSERT INTO audit_logs (     audit_id,     actor_user_id,     action,     entity_type,     entity_id,     before_json,     after_json,     reason,     created_at   )   VALUES (     lower(hex(randomblob(16))),     NEW.reviewed_by,     'REGISTRATION_CANCELLED',     'USER_REGISTRATION',     NEW.user_id,     json_object(       'registration_status', OLD.registration_status,       'account_status', 'DISABLED'     ),     json_object(       'registration_status', NEW.registration_status,       'account_status', 'DISABLED',       'cancelled_by', NEW.reviewed_by,       'cancelled_at', NEW.reviewed_at     ),     NEW.cancellation_reason,     NEW.reviewed_at   ); END;
CREATE TRIGGER trg_user_account_archive_validate BEFORE INSERT ON user_account_archives BEGIN     SELECT CASE         WHEN NOT EXISTS (             SELECT 1             FROM users             WHERE user_id = NEW.user_id               AND account_status = NEW.previous_account_status         )         THEN RAISE(ABORT, 'Account status changed or account not found.')     END;      SELECT CASE         WHEN EXISTS (             SELECT 1             FROM user_roles             WHERE user_id = NEW.user_id               AND role_id = 'role-super-admin'         )         THEN RAISE(ABORT, 'SUPER_ADMIN account cannot be archived.')     END;      SELECT CASE         WHEN NEW.user_id = NEW.archived_by         THEN RAISE(ABORT, 'Self-archiving is not permitted.')     END;      SELECT CASE         WHEN NOT EXISTS (             SELECT 1             FROM user_roles ur             INNER JOIN users u                 ON u.user_id = ur.user_id             WHERE ur.user_id = NEW.archived_by               AND ur.role_id = 'role-super-admin'               AND u.account_status = 'ACTIVE'         )         THEN RAISE(ABORT, 'Active SUPER_ADMIN authorization required.')     END;      SELECT CASE         WHEN EXISTS (             SELECT 1             FROM user_country_assignments             WHERE user_id = NEW.user_id               AND assignment_status = 'ACTIVE'         )         THEN RAISE(ABORT, 'Revoke active country assignments before archiving.')     END; END;
CREATE TRIGGER trg_user_account_archive_apply AFTER INSERT ON user_account_archives BEGIN     UPDATE users     SET         account_status = 'SUSPENDED',         updated_at = NEW.archived_at     WHERE user_id = NEW.user_id;      INSERT INTO audit_logs (         audit_id,         actor_user_id,         action,         entity_type,         entity_id,         before_json,         after_json,         reason,         created_at     )     VALUES (         lower(hex(randomblob(16))),         NEW.archived_by,         'USER_ACCOUNT_ARCHIVED',         'USER_ACCOUNT',         NEW.user_id,         json_object(             'account_status', NEW.previous_account_status         ),         json_object(             'account_status', 'SUSPENDED',             'archive_id', NEW.archive_id,             'archived_at', NEW.archived_at         ),         NEW.archive_reason,         NEW.archived_at     ); END;
CREATE TRIGGER trg_user_account_archive_restore_validate BEFORE UPDATE OF restored_by, restored_at, restore_reason ON user_account_archives BEGIN     SELECT CASE         WHEN OLD.restored_at IS NOT NULL         THEN RAISE(ABORT, 'Archive record has already been restored.')     END;      SELECT CASE         WHEN NEW.restored_at IS NULL           OR NEW.restored_by IS NULL           OR NEW.restore_reason IS NULL           OR length(trim(NEW.restore_reason)) NOT BETWEEN 10 AND 1000         THEN RAISE(ABORT, 'Valid restoration details are required.')     END;      SELECT CASE         WHEN NOT EXISTS (             SELECT 1             FROM user_roles ur             INNER JOIN users u                 ON u.user_id = ur.user_id             WHERE ur.user_id = NEW.restored_by               AND ur.role_id = 'role-super-admin'               AND u.account_status = 'ACTIVE'         )         THEN RAISE(ABORT, 'Active SUPER_ADMIN authorization required.')     END;      SELECT CASE         WHEN NOT EXISTS (             SELECT 1             FROM users             WHERE user_id = NEW.user_id               AND account_status = 'SUSPENDED'         )         THEN RAISE(ABORT, 'Archived account status is invalid.')     END; END;
CREATE TRIGGER trg_user_account_archive_apply_restore AFTER UPDATE OF restored_at ON user_account_archives WHEN OLD.restored_at IS NULL  AND NEW.restored_at IS NOT NULL BEGIN     UPDATE users     SET         account_status = NEW.previous_account_status,         updated_at = NEW.restored_at     WHERE user_id = NEW.user_id;      INSERT INTO audit_logs (         audit_id,         actor_user_id,         action,         entity_type,         entity_id,         before_json,         after_json,         reason,         created_at     )     VALUES (         lower(hex(randomblob(16))),         NEW.restored_by,         'USER_ACCOUNT_RESTORED',         'USER_ACCOUNT',         NEW.user_id,         json_object(             'account_status', 'SUSPENDED',             'archive_id', NEW.archive_id         ),         json_object(             'account_status', NEW.previous_account_status,             'restored_at', NEW.restored_at         ),         NEW.restore_reason,         NEW.restored_at     ); END;
CREATE TRIGGER trg_registration_review_transition_guard BEFORE UPDATE OF registration_status ON user_registration_reviews WHEN NEW.registration_status <> OLD.registration_status BEGIN   SELECT CASE     WHEN OLD.registration_status = 'AWAITING_EMAIL_VERIFICATION'       AND NEW.registration_status = 'PENDING_REVIEW'       AND (         NEW.reviewed_by IS NOT NULL         OR NEW.reviewed_at IS NOT NULL         OR NEW.rejection_reason IS NOT NULL         OR NEW.cancellation_reason IS NOT NULL         OR NOT EXISTS (           SELECT 1           FROM users u           WHERE u.user_id = NEW.user_id             AND u.account_status = 'DISABLED'             AND u.email IS NOT NULL         )         OR NOT EXISTS (           SELECT 1           FROM user_auth_identities i           WHERE i.user_id = NEW.user_id             AND i.identity_type = 'EMAIL'             AND i.identity_scope = 'GLOBAL'             AND i.verification_status = 'VERIFIED'             AND i.verified_at IS NOT NULL             AND i.expires_at IS NULL         )       )     THEN RAISE(       ABORT,       'Email verification must be completed before registration review.'     )   END;    SELECT CASE     WHEN OLD.registration_status = 'PENDING_REVIEW'       AND NEW.registration_status IN ('APPROVED', 'REJECTED')     THEN NULL     WHEN OLD.registration_status = 'AWAITING_EMAIL_VERIFICATION'       AND NEW.registration_status = 'PENDING_REVIEW'     THEN NULL     ELSE RAISE(       ABORT,       'Invalid registration status transition.'     )   END;    SELECT CASE     WHEN NEW.registration_status IN ('APPROVED', 'REJECTED')       AND (         NEW.reviewed_by IS NULL         OR NEW.reviewed_at IS NULL       )     THEN RAISE(       ABORT,       'Reviewer identity and review timestamp are required.'     )   END;    SELECT CASE     WHEN NEW.registration_status IN ('APPROVED', 'REJECTED')       AND NOT EXISTS (         SELECT 1         FROM user_roles ur         JOIN roles r           ON r.role_id = ur.role_id         WHERE ur.user_id = NEW.reviewed_by           AND r.role_code IN ('ADMIN', 'SUPER_ADMIN')       )     THEN RAISE(       ABORT,       'Only Admin or Super Admin can review registrations.'     )   END;    SELECT CASE     WHEN NEW.registration_status IN ('APPROVED', 'REJECTED')       AND NOT EXISTS (         SELECT 1         FROM users u         WHERE u.user_id = NEW.user_id           AND u.account_status = 'DISABLED'       )     THEN RAISE(       ABORT,       'Registration account must remain disabled before review.'     )   END;    SELECT CASE     WHEN NEW.registration_status = 'REJECTED'       AND (         NEW.rejection_reason IS NULL         OR length(trim(NEW.rejection_reason)) = 0       )     THEN RAISE(       ABORT,       'Rejection reason is required.'     )   END;    SELECT CASE     WHEN NEW.registration_status = 'APPROVED'       AND NEW.rejection_reason IS NOT NULL     THEN RAISE(       ABORT,       'Approved registration cannot have a rejection reason.'     )   END; END;
CREATE TRIGGER trg_auth_identity_manual_verification_insert BEFORE INSERT ON user_auth_identities WHEN   (     NEW.verification_method = 'ADMIN_MANUAL'     AND (       NEW.verified_by IS NULL       OR NEW.verification_status <> 'VERIFIED'       OR NEW.verified_at IS NULL     )   )   OR   (     NEW.verified_by IS NOT NULL     AND (       NEW.verification_method IS NULL       OR NEW.verification_method <> 'ADMIN_MANUAL'     )   ) BEGIN   SELECT RAISE(     ABORT,     'Invalid manual identity verification metadata.'   ); END;
CREATE TRIGGER trg_auth_identity_manual_verification_update BEFORE UPDATE OF   verification_method,   verified_by,   verification_status,   verified_at ON user_auth_identities WHEN   (     NEW.verification_method = 'ADMIN_MANUAL'     AND (       NEW.verified_by IS NULL       OR NEW.verification_status <> 'VERIFIED'       OR NEW.verified_at IS NULL     )   )   OR   (     NEW.verified_by IS NOT NULL     AND (       NEW.verification_method IS NULL       OR NEW.verification_method <> 'ADMIN_MANUAL'     )   ) BEGIN   SELECT RAISE(     ABORT,     'Invalid manual identity verification metadata.'   ); END;
